import math


def countPerfectSquareDigitSums(n):
    digits = [int(c) for c in str(n)]
    L = len(digits)
    max_s = 81 * L
    ways = [[0] * (max_s + 1) for _ in range(L + 1)]
    ways[0][0] = 1
    for t in range(1, L + 1):
        for s in range(max_s + 1):
            total = 0
            for d in range(10):
                if s - d * d >= 0:
                    total += ways[t - 1][s - d * d]
            ways[t][s] = total

    def is_square(v):
        r = math.isqrt(v)
        return r * r == v

    count = 0
    prefix = 0
    for i, dig in enumerate(digits):
        rest = L - i - 1
        for d in range(dig):
            base = prefix + d * d
            for s in range(81 * rest + 1):
                w = ways[rest][s]
                if w and base + s >= 1 and is_square(base + s):
                    count += w
        prefix += dig * dig
    if prefix >= 1 and is_square(prefix):
        count += 1
    return count
